const error = $input.first().json;

// === Meta del workflow + execution ===
const workflowName = error.workflow?.name      || 'unknown_workflow';
const workflowId   = error.workflow?.id        || null;
const executionId  = error.execution?.id       || 'unknown_execution';
const errorNode    = error.execution?.lastNodeExecuted || 'unknown_node';
const timestamp    = new Date().toISOString();
const errorObj     = error.execution?.error || error.error || {};
const errorMessage = errorObj.message || 'Error desconocido';
const errorStack   = errorObj.stack   || null;
const errorName    = errorObj.name    || 'Error';

// === Resolver project_id desde el runData ===
let projectId = null;
let projectIdSource = null;
try {
  const execData = error.execution?.data?.resultData?.runData;
  if (execData) {
    for (const nodeName of Object.keys(execData)) {
      const nodeRuns = execData[nodeName];
      if (!nodeRuns?.[0]?.data?.main?.[0]?.[0]?.json) continue;
      const j = nodeRuns[0].data.main[0][0].json;
      const candidates = [j.project_id, j.body?.project_id, j.params?.id];
      for (const c of candidates) {
        if (typeof c === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(c)) {
          projectId = c;
          projectIdSource = nodeName;
          break;
        }
      }
      if (projectId) break;
    }
  }
} catch(e) {}

// === Categorizacion ampliada ===
const em = errorMessage.toLowerCase();
let category = 'unknown';
if (em.match(/(timeout|etimedout|socket hang up|econnreset|enetunreach)/)) category = 'network';
else if (em.match(/(row.level.security|rls|policy.*violates|new row violates row.level security)/)) category = 'rls_violation';
else if (em.match(/(tenant_id .* null|current_tenant.*null|app\.current_tenant)/)) category = 'tenant_missing';
else if (em.match(/(postgres|relation .* does not exist|column .* does not exist|syntax error|constraint|unique violation|foreign key)/)) category = 'database';
else if (em.match(/(openai|anthropic|rate limit|insufficient_quota|model_not_found|context_length|api[_ ]key)/)) category = 'llm';
else if (em.match(/(unauthorized|forbidden|invalid token|jwt|auth)/)) category = 'auth';
else if (em.match(/(json|parse|invalid expression|unmatched)/)) category = 'parse';

// === Severity ===
const criticalWorkflows = ['main_orchestrator', 'agent_proposal', 'agent_trades', 'init_new_project'];
const criticalCategories = ['rls_violation', 'tenant_missing'];
const isCritical = criticalWorkflows.includes(workflowName) || criticalCategories.includes(category);

// === Hash de error (dedup) ===
let h = 5381;
const hashInput = workflowName + '|' + errorNode + '|' + (errorMessage.slice(0, 200));
for (let i = 0; i < hashInput.length; i++) { h = ((h << 5) + h) + hashInput.charCodeAt(i); h = h & h; }
const errorHash = Math.abs(h).toString(16).slice(0, 12);

// === Silent workflows ===
const silentPattern = /(_TEMP$|^debug|^test_|TEMP|migration_)/i;
const isSilent = silentPattern.test(workflowName);

// === details jsonb (lo nuevo en v2) ===
const details = {
  workflow_id:       workflowId,
  workflow_name:     workflowName,
  execution_id:      executionId,
  error_node:        errorNode,
  error_name:        errorName,
  error_message:     errorMessage.slice(0, 2000),
  error_stack:       errorStack ? errorStack.slice(0, 2000) : null,
  error_category:    category,
  error_hash:        errorHash,
  is_critical:       isCritical,
  project_id_source: projectIdSource,
  url_to_execution:  workflowId ? ('https://n8n-n8n.zzeluw.easypanel.host/workflow/' + workflowId + '/executions/' + executionId) : null
};

return [{
  json: {
    workflow_name: workflowName,
    project_id:    projectId,
    error_message: errorMessage.slice(0, 500),
    error_summary: '[' + workflowName + '] ' + errorNode + ' ' + category + ': ' + errorMessage.slice(0, 200),
    is_critical:   isCritical,
    is_silent:     isSilent,
    error_hash:    errorHash,
    error_category: category,
    timestamp,
    details
  }
}];
